//! Generates `source/extensions/dynamic_modules/sdk/rust/src/abi.rs`, the Rust bindings of the
//! dynamic modules ABI (`abi.h`), which are checked in.
//!
//! The bindings used to be generated by the SDK's build script, which made bindgen and its ~60
//! transitive crates a build dependency of the SDK: a serial chain of single-core compiles of
//! around ten minutes on every cold CI leg. Generating them once and checking them in keeps that
//! cost out of the build; `//tools/dynamic_modules/bindgen:abi_bindings_test` checks they match
//! the header and `bazel run //tools/dynamic_modules/bindgen:fix` regenerates them.
//!
//! ```text
//! envoy-dynamic-modules-bindgen --header abi.h --output abi.rs [--check]
//! ```
//!
//! Under Bazel the clang resource directory and sysroot are passed through the `ENVOY_LLVM_*` and
//! `ENVOY_SYSROOT_*` environment variables, as the build script used to take them; elsewhere
//! clang-sys finds the system clang.

use std::env;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

const BANNER: &str = concat!(
  "// Generated by //tools/dynamic_modules/bindgen from ",
  "source/extensions/dynamic_modules/abi/abi.h. Do not edit; run ",
  "`bazel run //tools/dynamic_modules/bindgen:fix` after changing the header.\n\n"
);

// Resolves a `$(location ...)` value produced by Bazel to an absolute path.
//
// `$(location ...)` yields a path relative to the execroot, but the current working directory of
// a Bazel-invoked binary isn't guaranteed to *be* the execroot. So we canonicalize against the
// current working directory, and if that doesn't exist, we walk up parent directories of the
// current working directory until the relative path resolves.
fn resolve_bazel_location(location: &str) -> Option<PathBuf> {
  let mut dir = env::current_dir().ok()?;
  loop {
    let candidate = dir.join(location);
    if candidate.exists() {
      return candidate.canonicalize().ok();
    }
    if !dir.pop() {
      return None;
    }
  }
}

// Derives the clang resource directory arguments from the anchor environment variables set by
// the Bazel wrapper, so the hermetic clang's builtin headers are used. A plain `cargo run` leaves
// them unset, in which case this returns an empty vector and clang-sys uses the system clang.
fn bazel_clang_args() -> Vec<String> {
  let mut args = Vec::new();

  if let Ok(llvm_anchor) = env::var("ENVOY_LLVM_ANCHOR") {
    if let Some(anchor) = resolve_bazel_location(&llvm_anchor) {
      // The anchor is `<llvm repo root>/lib/libclang.so`, so its grandparent is the repo root.
      if let Some(root) = anchor.parent().and_then(Path::parent) {
        let llvm_major = env::var("ENVOY_LLVM_MAJOR").unwrap_or_default();
        args.push("-resource-dir".to_string());
        args.push(format!("{}/lib/clang/{}", root.display(), llvm_major));
      }
    }
  }

  args
}

#[derive(Debug)]
// This allows us to simplify the enum variant names.
// Otherwise, the generated enum result would be `EnumName::EnumName_VariantName`. E.g.
// `envoy_dynamic_module_type_on_http_filter_response_trailers_status::envoy_dynamic_module_type_on_http_filter_response_trailers_status_Continue`
// instead of `envoy_dynamic_module_type_on_http_filter_response_trailers_status::Continue`.
//
// See https://github.com/rust-lang/rust-bindgen/issues/777
struct TrimEnumNameFromVariantName;

impl bindgen::callbacks::ParseCallbacks for TrimEnumNameFromVariantName {
  fn enum_variant_name(
    &self,
    enum_name: Option<&str>,
    original_variant_name: &str,
    _variant_value: bindgen::callbacks::EnumVariantValue,
  ) -> Option<String> {
    let variant_name = match enum_name {
      Some(enum_name) => original_variant_name
        .trim_start_matches(enum_name.trim_start_matches("enum "))
        .trim_start_matches('_'),
      None => original_variant_name,
    };
    Some(variant_name.to_string())
  }
}

#[derive(Debug)]
// Derives strum_macros::{FromRepr,VariantArray} for envoy_dynamic_module_type_response_flag:
// FromRepr gives a bit-index -> flag lookup and VariantArray gives Self::VARIANTS, both generated
// from the bindgen-derived enum definition itself to prevent version skew issues.
struct StrumDerivesForResponseFlag;

impl bindgen::callbacks::ParseCallbacks for StrumDerivesForResponseFlag {
  fn add_derives(&self, info: &bindgen::callbacks::DeriveInfo<'_>) -> Vec<String> {
    if info.name == "envoy_dynamic_module_type_response_flag" {
      vec![
        "strum_macros::FromRepr".to_string(),
        "strum_macros::VariantArray".to_string(),
      ]
    } else {
      vec![]
    }
  }
}

struct Args {
  header: PathBuf,
  output: PathBuf,
  check: bool,
}

fn parse_args() -> Result<Args, String> {
  let mut header = None;
  let mut output = None;
  let mut check = false;
  let mut args = env::args().skip(1);
  while let Some(arg) = args.next() {
    match arg.as_str() {
      "--header" => header = Some(PathBuf::from(args.next().ok_or("--header needs a path")?)),
      "--output" => output = Some(PathBuf::from(args.next().ok_or("--output needs a path")?)),
      "--check" => check = true,
      other => return Err(format!("unknown argument {other:?}")),
    }
  }
  Ok(Args {
    header: header.ok_or("--header is required")?,
    output: output.ok_or("--output is required")?,
    check,
  })
}

fn generate(header: &Path) -> Result<String, String> {
  let bindings = bindgen::Builder::default()
    .header(header.to_str().ok_or("header path is not UTF-8")?)
    // The generated file is canonical, so parse for one fixed target wherever this runs: C enum
    // underlying types (and so the `repr`) follow the target ABI, MSVC's `int` against the
    // Itanium ABI's `unsigned int`. Freestanding, the header's <stdint.h>/<stddef.h>/<stdbool.h>
    // come from clang's own resource directory, so no system headers of any platform are read.
    .clang_args(["--target=x86_64-unknown-linux-gnu", "-ffreestanding"])
    .clang_args(bazel_clang_args())
    // Generate for one canonical target whatever the host: the ABI's plain C enums have no fixed
    // underlying type, so clang gives them `unsigned int` on Linux but `int` on MSVC, which would
    // change the `repr` bindgen emits. The header only includes freestanding standard headers,
    // which come from clang's own resource directory on every host.
    .clang_arg("--target=x86_64-unknown-linux-gnu")
    // Only the ABI itself. Everything the system headers it includes declare would otherwise be
    // generated too, and differ between platforms; this keeps the file platform-independent.
    .allowlist_item("envoy_.*")
    .default_enum_style(bindgen::EnumVariation::Rust {
      non_exhaustive: false,
    })
    .derive_partialeq(true)
    // A dynamic module DLL on Windows imports the Envoy callbacks from `envoy.dll`; the SDK's
    // build script sets the cfg when building one (see src/windows_delay_load.rs).
    .extern_block_attrs(
      "#[cfg_attr(envoy_dynamic_module_dll, link(name = \"envoy\", kind = \"raw-dylib\"))]",
    )
    // prettyplease is pinned with bindgen, so the output does not depend on which rustfmt is
    // around; the checked-in file is excluded from the rustfmt check (rustfmt.toml).
    .formatter(bindgen::Formatter::Prettyplease)
    .parse_callbacks(Box::new(TrimEnumNameFromVariantName))
    .parse_callbacks(Box::new(StrumDerivesForResponseFlag))
    .generate()
    .map_err(|e| format!("bindgen failed: {e}"))?;
  Ok(format!("{BANNER}{bindings}"))
}

fn main() -> ExitCode {
  let args = match parse_args() {
    Ok(args) => args,
    Err(e) => {
      eprintln!("error: {e}");
      return ExitCode::from(2);
    },
  };
  let generated = match generate(&args.header) {
    Ok(generated) => generated,
    Err(e) => {
      eprintln!("error: {e}");
      return ExitCode::FAILURE;
    },
  };
  if args.check {
    let current = std::fs::read_to_string(&args.output).unwrap_or_default();
    if current == generated {
      return ExitCode::SUCCESS;
    }
    eprintln!(
      "error: {} is out of date with respect to {}; run `bazel run \
       //tools/dynamic_modules/bindgen:fix`",
      args.output.display(),
      args.header.display()
    );
    return ExitCode::FAILURE;
  }
  if let Err(e) = std::fs::write(&args.output, generated) {
    eprintln!("error: writing {}: {e}", args.output.display());
    return ExitCode::FAILURE;
  }
  ExitCode::SUCCESS
}
